application.css:
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@700;800&display=swap');

:root { --ink:#172126; --muted:#718087; --line:#dce5e5; --mint:#b9ead8; --deep:#165f58; --soft:#f5f9f7; --coral:#e8876e; }
* { box-sizing:border-box; }
body { margin:0; min-height:100vh; color:var(--ink); background:#eef5f2; font-family:'DM Sans', sans-serif; }
.shell { max-width:1120px; margin:auto; padding:58px 28px 34px; }
.hero { position:relative; padding:0 8px 48px; }
.eyebrow,.section-kicker { color:#438277; font-size:11px; font-weight:700; letter-spacing:1.8px; text-transform:uppercase; }
.hero h1 { max-width:600px; margin:13px 0 12px; font-family:Manrope,sans-serif; font-size:clamp(38px,5vw,62px); line-height:1.08; letter-spacing:-2.5px; }
.hero p { max-width:480px; margin:0; color:var(--muted); font-size:16px; line-height:1.7; }
.hero-detail { margin-top:23px; color:#52716c; font-size:12px; font-weight:600; }
.detail-dot { display:inline-block; width:7px; height:7px; margin-right:8px; border-radius:50%; background:#61b89e; box-shadow:0 0 0 5px #d8f1e8; }
.workspace { display:grid; grid-template-columns:minmax(320px,430px) 1fr; gap:28px; align-items:start; }
.form-card,.bookings-panel { border:1px solid #dce9e4; border-radius:20px; background:rgba(255,255,255,.9); box-shadow:0 14px 35px rgba(39,77,69,.07); }
.form-card { padding:30px; }
.card-heading,.panel-heading { display:flex; justify-content:space-between; align-items:flex-start; margin-bottom:27px; }
.section-kicker { font-size:10px; }
h2 { margin:7px 0 0; font-family:Manrope,sans-serif; font-size:22px; letter-spacing:-.6px; }
.calendar-mark { display:grid; place-items:center; width:38px; height:38px; border-radius:12px; color:var(--deep); background:var(--mint); font-size:20px; }
.field { margin-bottom:17px; }
.form-row { display:grid; grid-template-columns:1fr 1fr; gap:14px; }
label { display:block; margin-bottom:8px; color:#48615f; font-size:12px; font-weight:700; }
input,select { width:100%; height:45px; padding:0 13px; border:1px solid var(--line); border-radius:9px; outline:none; color:var(--ink); background:#fbfdfc; font:inherit; font-size:13px; transition:.2s; }
input:focus,select:focus { border-color:#62ad9a; box-shadow:0 0 0 3px #dff3ec; }
input:invalid:not(:placeholder-shown) { border-color:#e5a08e; }
select { cursor:pointer; }
.primary-button { width:100%; height:48px; margin-top:4px; border:0; border-radius:10px; color:white; background:var(--deep); font:700 13px 'DM Sans'; cursor:pointer; transition:.2s; }
.primary-button:hover { background:#0d4c47; transform:translateY(-1px); }
.primary-button span { margin-left:9px; font-size:18px; vertical-align:-1px; }
.form-error { min-height:17px; margin:0 0 7px; color:#be604c; font-size:12px; }
.bookings-panel { min-height:390px; padding:30px; }
.panel-heading { margin-bottom:20px; }
.count { display:grid; place-items:center; min-width:31px; height:31px; border-radius:50%; color:var(--deep); background:#e2f3ec; font-size:12px; font-weight:700; }
.empty-state { padding:61px 25px; border:1px dashed #ceded9; border-radius:13px; text-align:center; }
.empty-icon { margin:auto; color:#65a898; font-size:38px; }
.empty-state h3 { margin:13px 0 5px; font-size:15px; }
.empty-state p { margin:0; color:var(--muted); font-size:12px; }
.confirmation { margin-bottom:16px; padding:12px 14px; border:1px solid #b9e3d4; border-radius:9px; color:#286c5d; background:#edfaf4; font-size:13px; font-weight:600; }
.booking-list { display:flex; flex-direction:column; gap:12px; }
.booking { padding:18px; border:1px solid #e0e9e6; border-radius:13px; background:#fff; }
.booking.cancelled { opacity:.62; background:#f7f9f8; }
.booking-top { display:flex; justify-content:space-between; gap:12px; }
.booking-name { margin:0; font-size:15px; font-weight:700; }
.booking-type { margin:5px 0 0; color:#4c8278; font-size:12px; font-weight:600; }
.booking-details { display:flex; flex-wrap:wrap; gap:8px 16px; margin-top:16px; color:#687a7d; font-size:12px; }
.booking-details span { display:flex; gap:6px; align-items:center; }
.cancel-button { border:0; color:#a55b4c; background:transparent; font:600 12px 'DM Sans'; cursor:pointer; }
.cancel-button:hover { text-decoration:underline; }
.status-label { color:#a55b4c; font-size:11px; font-weight:700; text-transform:uppercase; letter-spacing:.6px; }
footer { margin-top:27px; color:#849693; text-align:center; font-size:11px; }
@media(max-width:760px) { .shell { padding:35px 18px 25px; } .hero { padding-bottom:32px; } .workspace { grid-template-columns:1fr; } .bookings-panel { min-height:300px; } }
@media(max-width:430px) { .form-card,.bookings-panel { padding:22px; } .form-row { gap:9px; } }

application.javascript:
const form = document.getElementById('booking-form');
const dateInput = document.getElementById('booking-date');
const list = document.getElementById('booking-list');
const emptyState = document.getElementById('empty-state');
const confirmation = document.getElementById('booking-confirmation');
const error = document.getElementById('form-error');
const count = document.getElementById('booking-count');
let bookings = [];

function todayString() {
  const now = new Date();
  const offset = now.getTimezoneOffset() * 60000;
  return new Date(now.getTime() - offset).toISOString().slice(0, 10);
}

dateInput.min = todayString();

function formatDate(value) {
  return new Date(value + 'T00:00:00').toLocaleDateString(undefined, { weekday:'short', month:'short', day:'numeric', year:'numeric' });
}
function formatTime(value) {
  const [hours, minutes] = value.split(':');
  const d = new Date();
  d.setHours(Number(hours), Number(minutes));
  return d.toLocaleTimeString([], { hour:'numeric', minute:'2-digit' });
}
function render() {
  list.querySelectorAll('[data-testid="booking"]').forEach(node => node.remove());
  emptyState.hidden = bookings.length > 0;
  count.textContent = bookings.filter(item => !item.cancelled).length;
  bookings.forEach(booking => {
    const article = document.createElement('article');
    article.className = 'booking' + (booking.cancelled ? ' cancelled' : '');
    article.dataset.testid = 'booking';
    article.dataset.status = booking.cancelled ? 'cancelled' : 'active';
    article.innerHTML = `<div class="booking-top"><div><p class="booking-name" data-testid="booking-name-display"></p><p class="booking-type"></p></div><div class="booking-action"></div></div><div class="booking-details"><span>▣ ${formatDate(booking.date)}</span><span>◷ ${formatTime(booking.time)}</span></div>`;
    article.querySelector('.booking-name').textContent = booking.name;
    article.querySelector('.booking-type').textContent = booking.type;
    const action = article.querySelector('.booking-action');
    if (booking.cancelled) {
      action.innerHTML = '<span class="status-label">Cancelled</span>';
    } else {
      const button = document.createElement('button');
      button.className = 'cancel-button';
      button.dataset.testid = 'booking-cancel';
      button.type = 'button';
      button.textContent = 'Cancel';
      button.addEventListener('click', () => { booking.cancelled = true; render(); });
      action.appendChild(button);
    }
    list.appendChild(article);
  });
}

form.addEventListener('submit', event => {
  event.preventDefault();
  error.textContent = '';
  if (!form.checkValidity()) {
    form.reportValidity();
    return;
  }
  const data = new FormData(form);
  const date = data.get('date');
  if (date < todayString()) {
    error.textContent = 'Please choose today or a future date.';
    dateInput.focus();
    return;
  }
  const booking = { name:data.get('name').trim(), email:data.get('email').trim(), date, time:data.get('time'), type:data.get('type'), cancelled:false };
  bookings.push(booking);
  render();
  confirmation.hidden = false;
  confirmation.textContent = `Appointment confirmed for ${booking.name} on ${formatDate(booking.date)}.`;
  form.reset();
  dateInput.min = todayString();
  window.setTimeout(() => { confirmation.hidden = true; }, 6000);
});

render();

