HTML:
<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Appointment Booking Form</title>
  <link rel="stylesheet" href="styles.css">
  <script src="script.js" defer></script>
</head>
<body>
  <main class="shell">
    <section class="hero">
      <div class="eyebrow">Simple scheduling</div>
      <h1>Plan time that matters.</h1>
      <p>Book a focused session in just a few moments. Your appointments stay private in this browser.</p>
      <div class="hero-detail"><span class="detail-dot"></span>No account required&nbsp; · &nbsp;Instant confirmation</div>
    </section>

    <section class="workspace">
      <div class="form-card">
        <div class="card-heading">
          <div>
            <div class="section-kicker">New appointment</div>
            <h2>Reserve a time</h2>
          </div>
          <div class="calendar-mark" aria-hidden="true">✦</div>
        </div>
        <form id="booking-form" novalidate>
          <div class="field">
            <label for="booking-name">Your name</label>
            <input id="booking-name" data-testid="booking-name" name="name" type="text" placeholder="e.g. Jordan Lee" autocomplete="name" required>
          </div>
          <div class="field">
            <label for="booking-email">Email address</label>
            <input id="booking-email" data-testid="booking-email" name="email" type="email" placeholder="you@example.com" autocomplete="email" required>
          </div>
          <div class="form-row">
            <div class="field">
              <label for="booking-date">Date</label>
              <input id="booking-date" data-testid="booking-date" name="date" type="date" required>
            </div>
